# get_opt ----
## Setup ----
fit_with_optimization_big <- FIMS::fit_with_optimization_big
fit_without_optimization_big <- FIMS:::fit_without_optimization_big
## IO correctness ----
test_that("`get_opt()` works with correct inputs", {
  optimized_opt <- get_opt(fit_with_optimization_big)
  #' @description Test that `get_opt()` returns the optimized fit slot.
  expect_equal(optimized_opt, fit_with_optimization_big@opt)
  expect_named(optimized_opt, names(fit_with_optimization_big@opt))

  deterministic_opt <- get_opt(fit_without_optimization_big)
  #' @description Test that `get_opt()` returns an empty list without optimization.
  expect_equal(deterministic_opt, list())
  expect_equal(deterministic_opt, fit_without_optimization_big@opt)
})

## Edge handling ----
test_that("`get_opt()` returns correct outputs for edge cases", {
  #' @description Test that `get_opt()` returns an error when given invalid input.
  expect_error(
    object = get_opt("invalid_input")
  )
})

## Error handling ----
# No built-in errors to test.
